def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = (change / v1) * 100

    return {
        "value": change_ratio,
        "trace": {
            "starting_value": v1,
            "ending_value": v2,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "percent"
            }
        }
    }
